export const MODEL_B2: number[] = [-0.32996342828440944, -0.10769176160895616, 0.03615690755448849, 0.04162559346055438, 0.1806598789415772, 0.13606558310984027, -0.32601852438255846, -0.33059854049509946, -0.13754560914258923, -0.10907962658384444, -0.1031008222911889, 0.05417243914685995, 0.062172200329183046, 0.1951452589819457, 0.1642277021773429, 0.01493632305247775, 0.07165883958344979, -0.10722884687996063, 0.16401030897597024, -0.1769049720370558, -0.06880678293584941, -0.041870036567176576, 0.20887780978409815, 0.23658744570745027, 0.17846001689710794, -0.000763845496839346, -0.04534961622640764, 0.21905205844031028, 0.058700575635871326, 0.18583465061952686, -0.12709432218020514, -0.10908078315024843, 0.2229376383895502, -0.10463740257663895, 0.14637074004563058, 0.010022574223063565, 0.1157999572963532, -0.14488517993785247];

export function predictFestivalOrNumber(features: number[]): { predictedClass: string; confidence: number } | null {
  if (!features || features.length !== 79) return null;
  
  // Layer 1
  const h1 = new Array(MODEL_B0.length);
  for (let j = 0; j < MODEL_B0.length; j++) {
    let sum = MODEL_B0[j] || 0;
    for (let i = 0; i < features.length; i++) {
      sum += (features[i] || 0) * (MODEL_W0[i]?.[j] || 0);
    }
    h1[j] = Math.max(0, sum);
  }

  // Layer 2
  const h2 = new Array(MODEL_B1.length);
  for (let j = 0; j < MODEL_B1.length; j++) {
    let sum = MODEL_B1[j] || 0;
    for (let i = 0; i < h1.length; i++) {
      sum += (h1[i] || 0) * (MODEL_W1[i]?.[j] || 0);
    }
    h2[j] = Math.max(0, sum);
  }

  // Output Layer
  const logits = new Array(MODEL_B2.length);
  let maxLogit = -Infinity;
  for (let j = 0; j < MODEL_B2.length; j++) {
    let sum = MODEL_B2[j] || 0;
    for (let i = 0; i < h2.length; i++) {
      sum += (h2[i] || 0) * (MODEL_W2[i]?.[j] || 0);
    }
    logits[j] = sum;
    if (sum > maxLogit) maxLogit = sum;
  }

  let expSum = 0;
  const probs = new Array(logits.length);
  for (let j = 0; j < logits.length; j++) {
    probs[j] = Math.exp(logits[j] - maxLogit);
    expSum += probs[j];
  }

  let bestIdx = 0;
  let bestProb = 0;
  for (let j = 0; j < probs.length; j++) {
    const prob = expSum > 0 ? probs[j] / expSum : 0;
    if (prob > bestProb) {
      bestProb = prob;
      bestIdx = j;
    }
  }

  return {
    predictedClass: FESTIVAL_AND_NUMBER_CLASSES[bestIdx] || "Unknown",
    confidence: bestProb
  };
}
